// Permitir updates para capturar adjuntos o cambios de estado\nif (!['message_created', 'message_updated', 'conversation_created', 'conversation_updated'].includes(webhookData.event)) {
    return []; 
}

// Encontrar al CONTACTO real (no al agente que responde)
let contacto = webhookData.conversation?.meta?.sender || webhookData.meta?.sender;
if (!contacto || (!contacto.name && !contacto.phone_number)) {
    if (webhookData.sender && webhookData.sender.type !== 'user' && webhookData.sender.type !== 'agent') {
        contacto = webhookData.sender;
    } else {
        contacto = {};
    }
}

let assignee = webhookData.conversation?.meta?.assignee || webhookData.meta?.assignee || webhookData.assignee || {};

let fullName = contacto.name || '';
let parts = fullName.split(" ");
let nombres = parts[0] || '';
let apellidos = parts.slice(1).join(" ") || '';

let telefono = contacto.phone_number || '';
let email = contacto.email || '';
let owner = assignee.name || '';

return [{
  json: {
    ...items[0].json,
    Nombres: nombres,
    Apellidos: apellidos,
    Telefono: telefono,
    Email: email,
    owner: owner
  }
}];

const item = $input.item.json;
const rawName = String(item.Nombres ?? '').trim();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/i;
const pareceCorreo = emailRegex.test(rawName) || (rawName.includes('@') && /\./.test(rawName));

let baseName = pareceCorreo ? rawName.split('@')[0] : rawName;
baseName = baseName.replace(/[._-]+/g, ' ');

const sinRuido = baseName
  .replace(/[^A-Za-z\u00C0-\u024F0-9\s.'-]/gu, ' ')
  .replace(/\s+/gu, ' ')
  .trim();

let capitalizado = sinRuido
  .split(' ')
  .filter(Boolean)
  .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
  .join(' ');

const soloLetras = (capitalizado.match(/[A-Za-z\u00C0-\u024F]/g) || []).length;
if (soloLetras < 2) { capitalizado = 'Contacto Chatwoot Por Actualizar'; }

const phone = String(item.Telefono ?? '').trim();
const email = String(item.Email ?? '').trim();

return {
  json: {
    ...item,
    Nombres: capitalizado,
    Nombres_crudo: rawName,
    nombre_extraido_desde_correo: pareceCorreo,
    Telefono: phone,
    Email: email
  },
};

const item = $input.item.json;
const filterGroups = [];

if (item.Email && item.Email.length > 0) {
  filterGroups.push({
    filters: [{ propertyName: "email", operator: "EQ", value: item.Email }]
  });
}

if (item.Telefono && item.Telefono.length > 0) {
  filterGroups.push({
    filters: [{ propertyName: "phone", operator: "EQ", value: item.Telefono }]
  });
  filterGroups.push({
    filters: [{ propertyName: "mobilephone", operator: "EQ", value: item.Telefono }]
  });
}

const tieneApellidos = (item.Apellidos || '').trim().length > 0;
const esNombreGenerico = item.Nombres === 'Contacto Chatwoot Por Actualizar';
if (tieneApellidos && !esNombreGenerico) {
  filterGroups.push({
    filters: [
      { propertyName: "firstname", operator: "CONTAINS_TOKEN", value: item.Nombres },
      { propertyName: "lastname", operator: "CONTAINS_TOKEN", value: item.Apellidos }
    ]
  });
}

return {
  json: {
    ...item,
    hubspot_search_body: {
      filterGroups: filterGroups,
      properties: ["firstname", "lastname", "phone", "mobilephone", "email", "hs_object_id", "hubspot_communication_id", "chatwoot_conversation_id"],
      limit: 1
    },
    puede_buscar: filterGroups.length > 0
  }
};

