            attachmentHtml += '<div style="margin-top: 5px; padding: 6px; background-color: rgba(0,0,0,0.05); border-radius: 4px; font-size: 12px;">📎 <b>Archivo:</b> <a href="' + url + '" target="_blank" style="color: #0056b3; text-decoration: none;">Descargar Archivo</a></div>';
        } else {
            // Indicador si no hay URL (raro pero posible)
            attachmentHtml += '<div style="margin-top: 5px; padding: 6px; background-color: rgba(0,0,0,0.05); border-radius: 4px; font-size: 12px; font-style: italic;">📎 [Archivo adjunto en Chatwoot]</div>';
        }
    });
}

// Combinar texto y adjuntos
let contentArea = '';
if (formattedContent) {
    contentArea += '<div style="font-size: 14px; line-height: 1.4;">' + formattedContent + '</div>';
}
if (attachmentHtml) {
    contentArea += attachmentHtml;
}
if (!contentArea) {
    contentArea = '<div style="font-size: 14px; line-height: 1.4; font-style: italic; color: #888;">[Multimedia]</div>';
}

// Hora formateada para la burbuja
let timeObj = new Date(hs_timestamp);
let timeString = timeObj.getHours().toString().padStart(2, '0') + ':' + timeObj.getMinutes().toString().padStart(2, '0');

let html_bubble = '';
if (is_incoming) {
    // Cliente (Izquierda, Gris)
    html_bubble = '<div style="text-align: left; margin-bottom: 12px; margin-top: 4px;">' +
      '<div style="display: inline-block; background-color: #f0f2f5; color: #1c1e21; padding: 10px 14px; border-radius: 0px 16px 16px 16px; text-align: left; max-width: 85%; border: 1px solid #e4e6eb; font-family: Helvetica, Arial, sans-serif;">' +
        '<div style="font-size: 11px; color: #65676b; margin-bottom: 4px;"><b>' + sender_name + '</b></div>' +
        contentArea +
        '<div style="font-size: 10px; color: #8a8d91; text-align: right; margin-top: 6px;">' + timeString + '</div>' +
      '</div>' +
    '</div>';
} else {
    // Agente (Derecha, Verde)
    html_bubble = '<div style="text-align: right; margin-bottom: 12px; margin-top: 4px;">' +
      '<div style="display: inline-block; background-color: #dcf8c6; color: #1c1e21; padding: 10px 14px; border-radius: 16px 0px 16px 16px; text-align: left; max-width: 85%; border: 1px solid #c2e0ab; font-family: Helvetica, Arial, sans-serif;">' +
        '<div style="font-size: 11px; color: #4b663b; margin-bottom: 4px;"><b>' + sender_name + '</b></div>' +
        contentArea +
        '<div style="font-size: 10px; color: #698a58; text-align: right; margin-top: 6px;">' + timeString + '</div>' +
      '</div>' +
    '</div>';
}

const saved_chatwoot_id = item.hubspot_search_result?.properties?.chatwoot_conversation_id || '';
const saved_communication_id = item.hubspot_search_result?.properties?.hubspot_communication_id || '';

const es_misma_conversacion = (saved_chatwoot_id === chatwoot_conversation_id) && saved_communication_id !== '';

return {
  json: {
    ...item,
    mensaje_actual: {
      content,
      sender_name,
      chatwoot_conversation_id,
      hs_timestamp,
      html_bubble
    },
    hubspot_data: {
      es_misma_conversacion,
      saved_communication_id
    }
  }
};
